def transform(grid):
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    motifs = []
    # Find the four 2s forming a diamond outline around an empty center.
    for r in range(1, H - 1):
        for c in range(1, W - 1):
            if (grid[r][c] == 0 and grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                motifs.append((r, c))
    # Bridge horizontally or vertically aligned diamonds with color 1.
    for i, (r, c) in enumerate(motifs):
        for rr, cc in motifs[i + 1:]:
            if r == rr:
                for x in range(min(c, cc) + 1, max(c, cc)):
                    if out[r][x] == 0:
                        out[r][x] = 1
            if c == cc:
                for x in range(min(r, rr) + 1, max(r, rr)):
                    if out[x][c] == 0:
                        out[x][c] = 1
    return out
